function Star({className=''}:{className?:string}){return <svg className={`star ${className}`} viewBox="0 0 64 64" fill="currentColor" aria-hidden="true"><path d="M32 0C34.5 25.5 38.5 29.5 64 32C38.5 34.5 34.5 38.5 32 64C29.5 38.5 25.5 34.5 0 32C25.5 29.5 29.5 25.5 32 0Z"/></svg>}
