function ErrorNotice({message}:{message:string}){return message?<div className="notice error" role="alert">{message}</div>:null;}
function Empty({title,children}:{title:string;children?:React.ReactNode}){return <div className="empty"><Star/><h3>{title}</h3><p>{children}</p></div>}
function App(){const[user,setUser]=useState<User|null>(null);const[loading,setLoading]=useState(true);async function refresh(){try{const data=await gql<{me:User|null}>('{me{id username email recoveryEmail role createdAt}}');setUser(data.me);}catch{setUser(null);}finally{setLoading(false);}}useEffect(()=>{void refresh();},[]);return <AuthContext.Provider value={{user,refresh,loading}}><BrowserRouter><ScrollTop/><Routes><Route path="/" element={<Landing/>}/><Route path="/login" element={<Auth/>}/><Route path="/autentificare" element={<Auth/>}/><Route path="/reset-password" element={<Recovery/>}/><Route path="/blog" element={<Blog/>}/><Route path="/blog/:slug" element={<Article/>}/><Route path="/proposal" element={<PublicProposal/>}/><Route path="/proposal/:slug" element={<PublicProposal/>}/><Route path="/propunere" element={<PublicProposal/>}/><Route path="/propunere/:slug" element={<PublicProposal/>}/>
<Route path="/ai/demo" element={<HostedAgentDemo siteHeader={<Header/>} siteFooter={<Footer/>}/>}/>
<Route path="/ai/demo/:slug" element={<HostedAgentDemo siteHeader={<Header/>} siteFooter={<Footer/>}/>}/>
<Route path="/ai/embed/:publicId" element={<HostedAgentEmbed/>}/>
<Route path="/ai/proposal/:slug" element={<HostedAgentProposal/>}/><Route path="/app/*" element={<Workspace/>}/><Route path="*" element={<NotFound/>}/></Routes></BrowserRouter></AuthContext.Provider>}
