function InteractiveQuestionBox({questionJson,onAnswer,disabled}:{questionJson?:string;onAnswer:(ans:string)=>void;disabled?:boolean}){
  const[customVal,setCustomVal]=useState('');
  const[customFocus,setCustomFocus]=useState(false);
  if(!questionJson)return null;
  let q:InteractiveQuestion|null=null;
  try{q=JSON.parse(questionJson);}catch{return null;}
  if(!q||!Array.isArray(q.options))return null;
  return (
    <div className="interactive-question-card">
      <div className="iq-options-list">
        {q.options.map((opt,idx)=>(
          <button
            type="button"
            key={idx}
            disabled={disabled}
            className={`iq-option-row ${opt.recommended?'recommended':''}`}
            onClick={()=>onAnswer(opt.value||opt.label)}
          >
            <span className="iq-num">{idx+1}</span>
            <span className="iq-label">{opt.label}</span>
            {opt.recommended&&<span className="iq-rec-badge">Recommended</span>}
            {opt.recommended&&<ArrowRight size={14} className="iq-arrow"/>}
          </button>
        ))}
        {q.allowCustom!==false&&(
          <form
            className={`iq-custom-row ${customFocus?'focused':''}`}
            onSubmit={e=>{
              e.preventDefault();
              if(customVal.trim()&&!disabled){onAnswer(customVal.trim());setCustomVal('');}
            }}
          >
            <span className="iq-num"><Pencil size={12}/></span>
            <input
              disabled={disabled}
              value={customVal}
              onFocus={()=>setCustomFocus(true)}
              onBlur={()=>setCustomFocus(false)}
              onChange={e=>setCustomVal(e.target.value)}
              placeholder={q.customPlaceholder||'Custom response (type your answer)…'}
            />
            {customVal.trim()&&(
              <button type="submit" className="iq-custom-send" disabled={disabled} aria-label="Submit response">
                <ArrowRight size={14}/>
              </button>
            )}
          </form>
        )}
      </div>
      {q.moreIdeasLabel&&(
        <div className="iq-footer-actions">
          <button
            type="button"
            disabled={disabled}
            className="iq-more-pill"
            onClick={()=>onAnswer(q!.moreIdeasPrompt||q!.moreIdeasLabel!)}
          >
            <RefreshCw size={12}/> {q.moreIdeasLabel}
          </button>
        </div>
      )}
    </div>
  );
}
